/* Home World v1 — shared core (loaded on demand by app.js).
 *
 * The everyday surface is the ambient strip above the chat (strip.js): a
 * chip that drops into a side-view strip while Hearth is thinking or when
 * pulled down. The full-screen pixel house (house.js) opens from the strip
 * and from Settings → Home World.
 *
 * Data comes only through the host helpers app.js passes in (host.api.*,
 * host.toggle, host.ask): the house structure is generated by the controller
 * from Home Assistant areas of in-scope entities plus the owner's saved
 * customization; values are controller reads. This module never builds URLs
 * or opens connections itself. Untrusted text (names, states, tool output)
 * is rendered with textContent / canvas fillText only.
 *
 * Motion: the avatar walks only when a real tool call (pi.live) names a
 * drawn device's entityId. Idle → no animation frames; hidden → paused;
 * 30 fps cap; prefers-reduced-motion → no walking (instant moves).
 */

export const PROTOTYPE_LAYOUT_KEY = "hearth-PROTOTYPE-world-layout";
export const FLOORS = {
  wood: "Wood",
  tile: "Tile",
  carpet: "Carpet",
  stone: "Stone",
  grass: "Garden",
};
export const PALETTES = [
  { name: "Ember", body: "#d9664a", trim: "#ffc58e", hair: "#4a2f22" },
  { name: "Sage", body: "#4f8f72", trim: "#d6efd0", hair: "#2e2a24" },
  { name: "Dusk", body: "#5f62b0", trim: "#dcdaff", hair: "#1f1a2e" },
  { name: "Sun", body: "#d9a12c", trim: "#fff2c2", hair: "#7a3f1d" },
];
export const HATS = {
  none: "No hat",
  beanie: "Beanie",
  cap: "Cap",
  bow: "Bow",
  crown: "Crown",
};
export const ANOMALY_TEXT = {
  unavailable: "Unavailable",
  open_at_night: "Open at night",
  low_battery: "Low battery",
  leak: "Leak detected",
};
export const FRAME_MS = 1000 / 30;
const VALUES_EVERY_MS = 30000;
const VALUES_MIN_GAP_MS = 5000;
const ACTIVE_STATES = new Set([
  "on",
  "open",
  "playing",
  "heat",
  "cool",
  "heat_cool",
  "auto",
  "dry",
  "fan_only",
  "cleaning",
  "unlocked",
]);

// ---------------------------------------------------------------- helpers
export function el(tag, options = {}, children = []) {
  const element = document.createElement(tag);
  if (options.className) element.className = options.className;
  if (options.text !== undefined) element.textContent = String(options.text);
  for (const [name, value] of Object.entries(options.attrs ?? {}))
    element.setAttribute(name, String(value));
  for (const child of children) if (child) element.append(child);
  return element;
}
export function button(text, className = "", label = "") {
  const b = el("button", { className, text, attrs: { type: "button" } });
  if (label) b.setAttribute("aria-label", label);
  return b;
}
export const reducedMotion = () =>
  !!globalThis.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
export const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
export function hash32(text) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
export const timeOf = (ms) =>
  ms
    ? new Date(ms).toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
      })
    : "—";

// --------------------------------------------------------- geometry/paths
export function roomAt(layout, x, y) {
  return (
    layout.rooms.find(
      (r) => x >= r.x && x < r.x + r.w && y >= r.y && y < r.y + r.h,
    ) ?? null
  );
}
// Doors: one tile-wide opening in the middle of every shared edge of ≥2 tiles.
export function doorsOf(layout) {
  const doors = [];
  const rooms = layout.rooms;
  for (let i = 0; i < rooms.length; i++)
    for (let j = i + 1; j < rooms.length; j++)
      for (const [p, q] of [
        [rooms[i], rooms[j]],
        [rooms[j], rooms[i]],
      ]) {
        if (p.x + p.w === q.x) {
          const lo = Math.max(p.y, q.y),
            hi = Math.min(p.y + p.h, q.y + q.h);
          if (hi - lo >= 2)
            doors.push({
              a: p.id,
              b: q.id,
              vertical: true,
              x: q.x,
              y: Math.floor((lo + hi - 1) / 2),
            });
        }
        if (p.y + p.h === q.y) {
          const lo = Math.max(p.x, q.x),
            hi = Math.min(p.x + p.w, q.x + q.w);
          if (hi - lo >= 2)
            doors.push({
              a: p.id,
              b: q.id,
              vertical: false,
              y: q.y,
              x: Math.floor((lo + hi - 1) / 2),
            });
        }
      }
  return doors;
}
// Wall segments in grid units with door openings removed.
export function wallsOf(layout) {
  const doors = doorsOf(layout);
  const walls = [];
  const seen = new Set();
  const push = (wall) => {
    const key = `${wall.vertical}|${wall.at}|${wall.from}|${wall.to}`;
    if (wall.to - wall.from <= 0 || seen.has(key)) return;
    seen.add(key);
    walls.push(wall);
  };
  for (const room of layout.rooms) {
    const edges = [
      { vertical: false, at: room.y, from: room.x, to: room.x + room.w },
      {
        vertical: false,
        at: room.y + room.h,
        from: room.x,
        to: room.x + room.w,
      },
      { vertical: true, at: room.x, from: room.y, to: room.y + room.h },
      {
        vertical: true,
        at: room.x + room.w,
        from: room.y,
        to: room.y + room.h,
      },
    ];
    for (const edge of edges) {
      const gaps = doors
        .filter(
          (d) =>
            d.vertical === edge.vertical &&
            (edge.vertical ? d.x === edge.at : d.y === edge.at) &&
            (d.a === room.id || d.b === room.id),
        )
        .map((d) => (edge.vertical ? d.y : d.x))
        .sort((p, q) => p - q);
      let from = edge.from;
      for (const gap of gaps) {
        push({ ...edge, from, to: gap });
        from = gap + 1;
      }
      push({ ...edge, from, to: edge.to });
    }
  }
  return walls;
}
// Waypoints (grid units) through doors, or null when no door path exists
// (e.g. another level): callers then move the avatar directly.
export function planPath(layout, from, to) {
  const start = roomAt(layout, from.x, from.y),
    goal = roomAt(layout, to.x, to.y);
  if (!start || !goal) return null;
  if (start.id === goal.id) return [to];
  const doors = doorsOf(layout);
  const previous = new Map([[start.id, null]]);
  const queue = [start.id];
  while (queue.length) {
    const id = queue.shift();
    if (id === goal.id) break;
    for (const door of doors) {
      const next = door.a === id ? door.b : door.b === id ? door.a : null;
      if (next && !previous.has(next)) {
        previous.set(next, { id, door });
        queue.push(next);
      }
    }
  }
  if (!previous.has(goal.id)) return null;
  const hops = [];
  for (let id = goal.id; previous.get(id); id = previous.get(id).id)
    hops.unshift({ door: previous.get(id).door, into: id });
  const points = [];
  for (const { door, into } of hops) {
    const target = layout.rooms.find((r) => r.id === into);
    if (door.vertical) {
      const east = target.x === door.x;
      const cy = door.y + 0.5;
      points.push({ x: door.x + (east ? -0.6 : 0.6), y: cy });
      points.push({ x: door.x + (east ? 0.6 : -0.6), y: cy });
    } else {
      const south = target.y === door.y;
      const cx = door.x + 0.5;
      points.push({ x: cx, y: door.y + (south ? -0.6 : 0.6) });
      points.push({ x: cx, y: door.y + (south ? 0.6 : -0.6) });
    }
  }
  points.push(to);
  return points;
}
const MARGIN = 0.6;
// Device positions in grid units from the room-relative fractions.
export function placeDevices(structure) {
  if (!structure) return [];
  const rooms = new Map(structure.rooms.map((r) => [r.id, r]));
  return structure.devices.flatMap((device) => {
    const room = rooms.get(device.room);
    if (!room) return [];
    return [
      {
        ...device,
        x: room.x + MARGIN + device.fx * Math.max(0, room.w - 2 * MARGIN),
        y: room.y + MARGIN + device.fy * Math.max(0, room.h - 2 * MARGIN),
      },
    ];
  });
}
export function placementFor(layout, x, y) {
  const room = roomAt(layout, x, y);
  if (!room) return null;
  const round = (v) => Math.round(v * 1000) / 1000;
  return {
    room: room.id,
    fx: round(
      clamp((x - room.x - MARGIN) / Math.max(0.01, room.w - 2 * MARGIN), 0, 1),
    ),
    fy: round(
      clamp((y - room.y - MARGIN) / Math.max(0.01, room.h - 2 * MARGIN), 0, 1),
    ),
  };
}

// ------------------------------------------------------------ data adapter
// Display info for one device from the structure plus the latest reads.
export function deviceView(device, valuesDoc) {
  const value = valuesDoc?.values?.[device.entityId];
  const control = valuesDoc?.controls?.[device.entityId] ?? null;
  const state = value?.state ?? "";
  const unit = value?.unit ?? "";
  return {
    ...device,
    name: value?.name || device.entityId,
    state,
    unit,
    value: !value
      ? "Not read yet"
      : !value.available
        ? "Unavailable"
        : unit
          ? `${state} ${unit}`
          : state,
    kind: value?.kind ?? fallbackKind(device.entityId),
    anomaly: value?.anomaly ?? "",
    observedAt: value?.observedAt ?? 0,
    active: ACTIVE_STATES.has(state.toLowerCase()),
    control,
  };
}
function fallbackKind(entityId) {
  const domain = entityId.split(".")[0];
  return (
    {
      light: "light",
      switch: "switch",
      climate: "climate",
      fan: "fan",
      media_player: "media",
      vacuum: "vacuum",
      lock: "lock",
      cover: "cover",
      binary_sensor: "binary",
    }[domain] ?? "sensor"
  );
}
export function roomName(structure, id) {
  return structure?.rooms.find((r) => r.id === id)?.name ?? "";
}
export const askAbout = (device) =>
  `Read ${device.entityId} now and explain its state. Compare only with observed earlier evidence in this session; do not infer physical effects or call services.`;
export function worldSummary(structure, views) {
  if (!structure) return "Home World is loading.";
  const lights = views.filter(
    (d) => (d.kind === "light" || d.kind === "switch") && d.active,
  ).length;
  const odd = views.filter((d) => d.anomaly).length;
  return `${structure.rooms.length} room${structure.rooms.length === 1 ? "" : "s"}, ${views.length} device${views.length === 1 ? "" : "s"}${views.some((d) => d.observedAt) ? `, ${lights} light${lights === 1 ? "" : "s"} or switch${lights === 1 ? "" : "es"} on${odd ? `, ${odd} need${odd === 1 ? "s" : ""} attention` : ""}` : ""}.`;
}

function messageText(message) {
  if (typeof message?.content === "string") return message.content;
  return (Array.isArray(message?.content) ? message.content : [])
    .filter((b) => b?.type === "text" && typeof b.text === "string")
    .map((b) => b.text)
    .join("\n")
    .trim();
}
function collectCalls(message, into) {
  if (!Array.isArray(message?.content)) return;
  for (const block of message.content)
    if (block?.type === "toolCall" && typeof block.id === "string")
      into.set(block.id, {
        name: String(block.name ?? ""),
        args:
          block.arguments && typeof block.arguments === "object"
            ? block.arguments
            : {},
      });
}
// Think mode comes only from the durable live document (pi.live): the
// running tool of the current round and its call's entityId argument.
export function deriveThink(snapshot, kind = "home") {
  const idle = { busy: false, callId: "", tool: "", entityId: "" };
  if (kind !== "home" || !snapshot?.view) return idle;
  const live = snapshot.view.docs?.["pi.live"] ?? {};
  if (!live.run) return idle;
  const calls = new Map();
  const entries = Array.isArray(snapshot.view.entries)
    ? snapshot.view.entries
    : [];
  for (const entry of entries.slice(-6))
    for (const message of Array.isArray(entry?.model) ? entry.model : [])
      collectCalls(message, calls);
  if (live.generation?.message) collectCalls(live.generation.message, calls);
  const tools = Array.isArray(live.tools) ? live.tools : [];
  const current =
    [...tools].reverse().find((t) => t?.status === "running") ??
    tools.find((t) => t?.status === "pending") ??
    null;
  if (!current || typeof current.callId !== "string")
    return { ...idle, busy: true };
  const call = calls.get(current.callId);
  const entityId =
    typeof call?.args?.entityId === "string" ? call.args.entityId : "";
  return {
    busy: true,
    callId: current.callId,
    tool: String(call?.name || current.name || ""),
    entityId,
  };
}
const TOOL_VERB = {
  ha_state_detail: "Reading",
  ha_propose_service: "Proposing a change to",
  ha_automation_config: "Checking",
  ha_automation_traces: "Checking",
  ha_automation_trace_detail: "Checking",
  ha_automation_activity: "Checking",
};
export function thinkLabel(think, device, room) {
  if (!think.busy) return "";
  if (device)
    return `${TOOL_VERB[think.tool] ?? "Looking at"} ${device.name}${room ? ` · ${room}` : ""}…`;
  if (think.tool === "ha_search_states") return "Searching your home…";
  if (think.tool === "ha_build_view") return "Arranging your home view…";
  if (/^app_|^catalog_/.test(think.tool)) return "Working on an app…";
  if (think.tool === "ha_discover_services")
    return "Checking what I may change…";
  return "Thinking…";
}
// Latest conversation lines for the house's dialogue box (plain text).
export function recentLines(snapshot, limit = 3) {
  const lines = [];
  const entries = Array.isArray(snapshot?.view?.entries)
    ? snapshot.view.entries
    : [];
  for (const entry of entries.slice(-8))
    for (const message of Array.isArray(entry?.model) ? entry.model : []) {
      if (message.role !== "user" && message.role !== "assistant") continue;
      const text = messageText(message);
      if (text)
        lines.push({
          who: message.role === "user" ? "You" : "Hearth",
          text: text.slice(0, 400),
        });
    }
  return lines.slice(-limit);
}

// ------------------------------------------------------- walking actors
export class Walker {
  constructor(x, y, speed) {
    Object.assign(this, { x, y, speed, path: [], dir: "down", phase: 0 });
  }
  get moving() {
    return this.path.length > 0;
  }
  goTo(points) {
    this.path = points.slice();
  }
  jump(point) {
    this.path = [];
    this.x = point.x;
    this.y = point.y;
  }
  step(dt) {
    const next = this.path[0];
    if (!next) return false;
    const dx = next.x - this.x,
      dy = next.y - this.y,
      d = Math.hypot(dx, dy),
      move = this.speed * dt;
    if (Math.abs(dx) > Math.abs(dy)) this.dir = dx > 0 ? "right" : "left";
    else if (d > 0.01) this.dir = dy > 0 ? "down" : "up";
    this.phase += dt * 8;
    if (d <= move) {
      this.x = next.x;
      this.y = next.y;
      this.path.shift();
    } else {
      this.x += (dx / d) * move;
      this.y += (dy / d) * move;
    }
    return this.path.length > 0;
  }
}
// The avatar (and pet) move only from follow(): a new running tool call
// whose entityId is a drawn device. Nothing else starts a walk — no idle
// wandering. Without motion (reduced motion) it jumps instead of walking.
export function createThinkActor({ motion, speed = 4, target, path }) {
  const hearth = new Walker(0, 0, speed);
  const pet = new Walker(0, 0, speed * 1.15);
  let key = "";
  let placed = false;
  const petSpot = () => ({
    x: hearth.x + (hearth.dir === "left" ? 0.9 : -0.9),
    y: hearth.y + 0.5,
  });
  return {
    hearth,
    pet,
    place(point) {
      if (placed || !point) return;
      placed = true;
      hearth.jump(point);
      pet.jump(petSpot());
    },
    follow(think, devices) {
      const device =
        think?.busy && think.entityId
          ? devices.find((d) => d.entityId === think.entityId)
          : null;
      if (!device) {
        key = "";
        return false;
      }
      const next = `${think.callId}|${device.entityId}|${device.x},${device.y}`;
      if (next === key) return false;
      key = next;
      placed = true;
      const stand = target(device);
      const points = motion ? path(hearth, stand) : null;
      if (!points) {
        hearth.jump(stand);
        pet.jump(petSpot());
        return false;
      }
      hearth.goTo(points);
      return true;
    },
    step(dt) {
      const walking = hearth.step(dt);
      if (walking) pet.goTo([petSpot()]);
      else if (pet.moving) pet.path = [petSpot()];
      pet.step(dt);
      return walking || pet.moving;
    },
    get moving() {
      return hearth.moving || pet.moving;
    },
  };
}

// Frames only when asked: invalidate() draws once; render() returning true
// keeps animating (capped at 30 fps) until it returns false. Hidden pages
// and off-screen elements draw nothing.
export function createRenderLoop(render, options = {}) {
  const raf =
    options.raf ?? ((fn) => globalThis.requestAnimationFrame?.(fn) ?? 0);
  const cancel =
    options.cancel ?? ((id) => globalThis.cancelAnimationFrame?.(id));
  const hidden = options.hidden ?? (() => !!globalThis.document?.hidden);
  let id = 0,
    last = 0,
    lastDraw = -Infinity,
    pending = false,
    visible = true,
    stopped = false;
  const frame = (now) => {
    id = 0;
    if (stopped || !visible || hidden()) return;
    if (!pending && now - lastDraw < FRAME_MS) return schedule();
    const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
    last = now;
    lastDraw = now;
    pending = false;
    if (render(dt, now)) schedule();
    else last = 0;
  };
  const schedule = () => {
    if (!id && !stopped && visible && !hidden()) id = raf(frame) || 0;
  };
  return {
    invalidate() {
      pending = true;
      schedule();
    },
    animate() {
      schedule();
    },
    setVisible(next) {
      visible = next;
      if (visible) {
        pending = true;
        schedule();
      }
    },
    get scheduled() {
      return !!id;
    },
    stop() {
      stopped = true;
      if (id) cancel(id);
      id = 0;
    },
  };
}
// Wires a loop to page visibility and (optionally) element intersection.
export function watchVisibility(loop, element) {
  const onVisibility = () => loop.setVisible(true);
  document.addEventListener("visibilitychange", onVisibility);
  const observer =
    element && typeof IntersectionObserver === "function"
      ? new IntersectionObserver((entries) =>
          loop.setVisible(entries.some((e) => e.isIntersecting)),
        )
      : null;
  observer?.observe(element);
  return () => {
    document.removeEventListener("visibilitychange", onVisibility);
    observer?.disconnect();
  };
}

// ------------------------------------------------------- shared widgets
// Device details: state, as-of, room/area and the two actions. The toggle
// goes through host.toggle (Home permissions broker); Ask only drafts.
export function createDeviceCard(ctx, device, options = {}) {
  const structure = ctx.structure;
  const room = roomName(structure, device.room);
  const card = el("div", {
    className: "world-card",
    attrs: { role: "group", "aria-label": `${device.name} details` },
  });
  const close = button("✕", "world-icon", "Close device details");
  close.addEventListener("click", () => ctx.select(null));
  const meta = [
    room,
    device.area && device.area !== room ? `Area: ${device.area}` : "",
    device.device ? `Device: ${device.device}` : "",
  ].filter(Boolean);
  card.append(
    el("div", { className: "world-card-head" }, [
      el("strong", { text: device.name }),
      close,
    ]),
    el("p", { className: "world-card-value", text: device.value }),
    el("p", {
      className: "world-card-meta",
      text: `${meta.join(" · ")}${meta.length ? " · " : ""}as of ${timeOf(device.observedAt)} · ${device.entityId}`,
    }),
  );
  if (device.anomaly)
    card.append(
      el("p", {
        className: "world-anomaly",
        text: `⚠ ${ANOMALY_TEXT[device.anomaly] ?? device.anomaly}`,
      }),
    );
  const actions = el("div", { className: "world-card-actions" });
  if (device.control) actions.append(...toggleControls(ctx, device));
  const ask = button("Ask Hearth about this", "world-secondary");
  ask.dataset.key = `${device.entityId}:ask-card`;
  ask.disabled = !ctx.canAsk();
  ask.addEventListener("click", () => ctx.ask(device));
  actions.append(ask);
  if (options.open) {
    const open = button("Open Home World", "world-secondary");
    open.addEventListener("click", () =>
      ctx.openFull({ entityId: device.entityId }),
    );
    actions.append(open);
  }
  card.append(actions);
  return card;
}
function toggleControls(ctx, device) {
  const on = device.state === "on";
  const label =
    device.state === "on" || device.state === "off"
      ? `Turn ${on ? "off" : "on"}`
      : "Toggle";
  const toggle = button(label, "world-primary");
  toggle.dataset.key = `${device.entityId}:toggle`;
  toggle.setAttribute("aria-label", `${label} ${device.name}`);
  toggle.disabled = !device.control.enabled || ctx.busyToggle(device.entityId);
  const reason = el("p", {
    className: "world-muted world-reason",
    text: device.control.reason,
  });
  toggle.addEventListener("click", () => ctx.toggle(device));
  return [toggle, reason];
}

// Screen-reader and keyboard parity: rooms → devices with the same actions.
export function createListView(ctx) {
  const root = el("div", {
    className: "world-list",
    attrs: { role: "region", "aria-label": "Home World list" },
  });
  const structure = ctx.structure;
  if (!structure) return root;
  const views = ctx.views();
  root.append(
    el("p", { className: "world-muted", text: worldSummary(structure, views) }),
  );
  for (const room of structure.rooms) {
    const devices = views.filter((d) => d.room === room.id);
    const section = el("section", {
      className: "world-list-room",
      attrs: { "aria-label": room.name },
    });
    section.append(
      el("h3", {
        text: room.name,
      }),
    );
    if (room.area && room.area !== room.name)
      section.append(
        el("p", { className: "world-muted", text: `Area: ${room.area}` }),
      );
    const list = el("ul");
    for (const device of devices) {
      const item = el("li", { className: "world-list-item" });
      const info = el("div", { className: "world-list-info" }, [
        el("strong", { text: device.name }),
        el("span", {
          className: "world-list-value",
          text: `${device.value} · as of ${timeOf(device.observedAt)}`,
        }),
      ]);
      if (device.anomaly)
        info.append(
          el("span", {
            className: "world-anomaly",
            text: `⚠ ${ANOMALY_TEXT[device.anomaly] ?? device.anomaly}`,
          }),
        );
      const actions = el("div", { className: "world-card-actions" });
      if (device.control) actions.append(...toggleControls(ctx, device));
      const ask = button("Ask Hearth", "world-secondary");
      ask.dataset.key = `${device.entityId}:ask`;
      ask.setAttribute("aria-label", `Ask Hearth about ${device.name}`);
      ask.disabled = !ctx.canAsk();
      ask.addEventListener("click", () => ctx.ask(device));
      actions.append(ask);
      item.append(info, actions);
      list.append(item);
    }
    if (!devices.length)
      list.append(el("li", { className: "world-muted", text: "No devices" }));
    section.append(list);
    root.append(section);
  }
  return root;
}

// Owner customization: names, floors, size/position, device rooms,
// character and pet. Saved on the server (ctx.edit.*), resettable.
export function createEditPanel(ctx, { onDone, onSelectRoom } = {}) {
  let selected = ctx.structure?.rooms[0]?.id ?? "";
  const panel = el("section", {
    className: "world-edit",
    attrs: { "aria-label": "Edit Home World" },
  });
  const done = button("Done", "world-primary");
  done.addEventListener("click", () => onDone?.());
  const status = el("p", {
    className: "world-muted",
    attrs: { role: "status", "aria-live": "polite" },
  });
  panel.append(
    el("div", { className: "world-edit-head" }, [
      el("div", {}, [
        el("strong", { text: "Edit home" }),
        el("p", {
          className: "world-muted",
          text: "Drag rooms, their corner or devices on the map. Saved for you on this Hearth.",
        }),
      ]),
      done,
    ]),
  );
  const roomSelect = el("select", { attrs: { "aria-label": "Room" } });
  const name = el("input", {
    attrs: {
      type: "text",
      maxlength: "24",
      "aria-label": "Room name",
      autocomplete: "off",
    },
  });
  const floor = el("select", { attrs: { "aria-label": "Floor style" } });
  for (const [id, label] of Object.entries(FLOORS)) {
    const option = el("option", { text: label });
    option.value = id;
    floor.append(option);
  }
  const stepper = (label, apply) => {
    const minus = button("−", "world-step", `${label} smaller`);
    const plus = button("＋", "world-step", `${label} larger`);
    const value = el("span", { className: "world-step-value" });
    minus.addEventListener("click", () => apply(-1));
    plus.addEventListener("click", () => apply(1));
    return {
      node: el("div", { className: "world-stepper" }, [
        el("span", { text: label }),
        minus,
        value,
        plus,
      ]),
      value,
    };
  };
  const room = () => ctx.structure?.rooms.find((r) => r.id === selected);
  const width = stepper("Width", (d) => {
    const r = room();
    if (r) ctx.edit.room(r.id, { w: clamp(r.w + d, 2, 16 - r.x) });
  });
  const height = stepper("Height", (d) => {
    const r = room();
    if (r) ctx.edit.room(r.id, { h: clamp(r.h + d, 2, 16) });
  });
  const move = el("div", {
    className: "world-move",
    attrs: { role: "group", "aria-label": "Move room" },
  });
  for (const [arrow, dx, dy, label] of [
    ["←", -1, 0, "left"],
    ["↑", 0, -1, "up"],
    ["↓", 0, 1, "down"],
    ["→", 1, 0, "right"],
  ]) {
    const b = button(arrow, "world-step", `Move room ${label}`);
    b.addEventListener("click", () => {
      const r = room();
      if (r)
        ctx.edit.room(r.id, {
          x: clamp(r.x + dx, 0, 16 - r.w),
          y: clamp(r.y + dy, 0, 64 - r.h),
        });
    });
    move.append(b);
  }
  roomSelect.addEventListener("change", () => {
    selected = roomSelect.value;
    onSelectRoom?.(selected);
    render();
  });
  name.addEventListener("change", () => {
    const r = room();
    const value = name.value.trim().slice(0, 24);
    if (r && value) ctx.edit.room(r.id, { name: value });
  });
  floor.addEventListener("change", () => {
    const r = room();
    if (r) ctx.edit.room(r.id, { floor: floor.value });
  });
  const deviceList = el("div", { className: "world-device-list" });
  const swatches = el("div", {
    className: "world-swatches",
    attrs: { role: "radiogroup", "aria-label": "Character colours" },
  });
  PALETTES.forEach((palette, index) => {
    const swatch = button("", "world-swatch", palette.name);
    swatch.dataset.palette = String(index);
    swatch.style.setProperty("--swatch", palette.body);
    swatch.setAttribute("role", "radio");
    swatch.addEventListener("click", () =>
      ctx.edit.character({ palette: index }),
    );
    swatches.append(swatch);
  });
  const hat = el("select", { attrs: { "aria-label": "Hat" } });
  for (const [id, label] of Object.entries(HATS)) {
    const option = el("option", { text: label });
    option.value = id;
    hat.append(option);
  }
  hat.addEventListener("change", () => ctx.edit.character({ hat: hat.value }));
  const pet = el("input", { attrs: { type: "checkbox" } });
  pet.addEventListener("change", () => ctx.edit.pet(pet.checked));
  const reset = button("Reset to auto layout", "world-danger");
  reset.addEventListener("click", () => {
    if (
      window.confirm(
        "Reset Home World to the automatic layout from your Home Assistant areas? Your room names, positions, device places and character choices are removed.",
      )
    )
      ctx.edit.reset();
  });
  panel.append(
    el("div", { className: "world-edit-body" }, [
      el("fieldset", {}, [
        el("legend", { text: "Room" }),
        roomSelect,
        el("label", { className: "world-field" }, [
          el("span", { text: "Name" }),
          name,
        ]),
        el("label", { className: "world-field" }, [
          el("span", { text: "Floor" }),
          floor,
        ]),
        el("div", { className: "world-row" }, [width.node, height.node]),
        move,
      ]),
      el("fieldset", {}, [el("legend", { text: "Devices" }), deviceList]),
      el("fieldset", {}, [
        el("legend", { text: "Hearth" }),
        swatches,
        el("label", { className: "world-field" }, [
          el("span", { text: "Hat" }),
          hat,
        ]),
        el("label", { className: "world-check" }, [
          pet,
          el("span", { text: "Pet companion" }),
        ]),
      ]),
      status,
      reset,
    ]),
  );
  function render() {
    const structure = ctx.structure;
    if (!structure?.rooms.length) {
      deviceList.replaceChildren();
      return;
    }
    if (!structure.rooms.some((r) => r.id === selected))
      selected = structure.rooms[0].id;
    const current = room();
    roomSelect.replaceChildren(
      ...structure.rooms.map((r) => {
        const option = el("option", { text: r.name });
        option.value = r.id;
        return option;
      }),
    );
    roomSelect.value = selected;
    if (document.activeElement !== name) name.value = current.name;
    floor.value = current.floor;
    width.value.textContent = String(current.w);
    height.value.textContent = String(current.h);
    for (const swatch of swatches.children)
      swatch.setAttribute(
        "aria-checked",
        String(Number(swatch.dataset.palette) === structure.character.palette),
      );
    hat.value = structure.character.hat;
    pet.checked = structure.pet;
    status.textContent = ctx.saveStatus();
    const focused = document.activeElement;
    if (focused && deviceList.contains(focused)) return;
    deviceList.replaceChildren(
      ...ctx.views().map((device) => {
        const pick = el("select", {
          attrs: { "aria-label": `Room for ${device.name}` },
        });
        for (const r of structure.rooms) {
          const option = el("option", { text: r.name });
          option.value = r.id;
          pick.append(option);
        }
        pick.value = device.room;
        pick.addEventListener("change", () =>
          ctx.edit.device(device.entityId, {
            room: pick.value,
            fx: 0.5,
            fy: 0.5,
          }),
        );
        return el("label", { className: "world-field" }, [
          el("span", { text: device.name }),
          pick,
        ]);
      }),
    );
  }
  render();
  return {
    element: panel,
    render,
    selectedRoom: () => selected,
    selectRoom(id) {
      selected = id;
      render();
    },
  };
}

// ------------------------------------------------------------ controller
// app.js calls mountWorld(host) once; update(input) on every snapshot.
export async function mountWorld(host) {
  const [{ createStrip }, { createHouse }] = await Promise.all([
    import("./strip.js"),
    import("./house.js"),
  ]);
  const listeners = new Set();
  const input = { snapshot: null, kind: "home", canDraft: false };
  let structure = null,
    values = null,
    think = deriveThink(null),
    house = null,
    custom = null,
    saveTimer = 0,
    saving = false,
    saveAgain = false,
    saveState = "",
    lastValues = 0,
    valuesTimer = 0,
    toggling = new Set(),
    notice = "",
    wantStrip = false;
  const notify = () => {
    for (const listener of listeners) listener();
  };
  const views = () => placeDevices(structure).map((d) => deviceView(d, values));
  const ctx = {
    host,
    get structure() {
      return structure;
    },
    get values() {
      return values;
    },
    get think() {
      return think;
    },
    get snapshot() {
      return input.snapshot;
    },
    get kind() {
      return input.kind;
    },
    get notice() {
      return notice;
    },
    views,
    canAsk: () => !!input.canDraft,
    busyToggle: (entityId) => toggling.has(entityId),
    saveStatus: () => saveState,
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    selected: null,
    select(entityId) {
      ctx.selected = entityId;
      notify();
    },
    ask(device) {
      host.ask(askAbout(device));
    },
    async toggle(device) {
      if (toggling.has(device.entityId)) return;
      toggling.add(device.entityId);
      notice = "Sending to Home permissions…";
      notify();
      try {
        notice = await host.toggle(device.entityId, (message) => {
          notice = message;
          void refreshValues(true);
        });
      } catch (error) {
        notice = error?.message ?? "Not sent.";
      } finally {
        toggling.delete(device.entityId);
        await refreshValues(true);
      }
    },
    openFull(options = {}) {
      if (!house) {
        house = createHouse(ctx, {
          onClose: () => {
            house?.destroy();
            house = null;
            host.showView(null);
            syncValues();
          },
        });
        host.showView(house.element);
      }
      if (options.entityId) ctx.select(options.entityId);
      if (options.edit) house.setEditing(true);
      syncValues();
      notify();
    },
    closeFull() {
      if (!house) return;
      house.destroy();
      house = null;
      host.showView(null);
      syncValues();
    },
    setStripOpen(open) {
      wantStrip = open;
      syncValues();
    },
    edit: {
      room(id, patch) {
        const room = structure?.rooms.find((r) => r.id === id);
        if (!room) return;
        Object.assign(room, patch);
        room.w = clamp(Math.round(room.w), 2, 16);
        room.h = clamp(Math.round(room.h), 2, 16);
        room.x = clamp(Math.round(room.x), 0, 16 - room.w);
        room.y = clamp(Math.round(room.y), 0, 64 - room.h);
        editable().rooms[id] = {
          name: room.name,
          x: room.x,
          y: room.y,
          w: room.w,
          h: room.h,
          floor: room.floor,
        };
        structure.grid.rows = Math.max(
          structure.grid.rows,
          ...structure.rooms.map((r) => r.y + r.h),
        );
        changed();
      },
      device(entityId, place) {
        const device = structure?.devices.find((d) => d.entityId === entityId);
        if (!device) return;
        Object.assign(device, place, { moved: true });
        editable().devices[entityId] = { ...place };
        changed();
      },
      character(patch) {
        if (!structure) return;
        Object.assign(structure.character, patch);
        editable().character = { ...structure.character };
        changed();
      },
      pet(on) {
        if (!structure) return;
        structure.pet = on;
        editable().pet = on;
        changed();
      },
      async reset() {
        if (!structure) return;
        clearTimeout(saveTimer);
        try {
          adopt(await host.api.reset({ baseRevision: structure.revision }));
          saveState = "Back to the automatic layout.";
        } catch (error) {
          await conflict(error);
        }
        notify();
      },
    },
  };
  function editable() {
    custom ??= structure.custom
      ? JSON.parse(JSON.stringify(structure.custom))
      : {
          rooms: {},
          devices: {},
          character: { ...structure.character },
          pet: structure.pet,
        };
    custom.character = { ...structure.character };
    custom.pet = structure.pet;
    return custom;
  }
  function adopt(next) {
    structure = next;
    custom = null;
  }
  function changed() {
    saveState = "Saving…";
    notify();
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => void save(), 700);
  }
  async function conflict(error) {
    if (error?.message === "world_layout_conflict") {
      try {
        adopt(await host.api.load());
      } catch {
        /* keep what we have */
      }
      saveState =
        "Home World changed in another window, so it was reloaded. Make your change again.";
    } else saveState = `Not saved: ${error?.message ?? "error"}.`;
  }
  async function save() {
    if (!structure || !custom) return;
    if (saving) {
      saveAgain = true;
      return;
    }
    saving = true;
    const body = { baseRevision: structure.revision, layout: custom };
    try {
      const result = await host.api.save(body);
      if (saveAgain) structure.revision = result.revision;
      else adopt(result);
      saveState = "Saved.";
    } catch (error) {
      await conflict(error);
    } finally {
      saving = false;
      if (saveAgain) {
        saveAgain = false;
        void save();
      }
      notify();
    }
  }
  async function load() {
    try {
      adopt(await host.api.load());
      await migratePrototype();
    } catch {
      notice = "Home World could not load. Chat is unaffected.";
    }
    notify();
  }
  // One-time import of the prototype's device-local layout, then cleared.
  async function migratePrototype() {
    let raw = null;
    try {
      raw = globalThis.localStorage?.getItem(PROTOTYPE_LAYOUT_KEY) ?? null;
    } catch {
      return;
    }
    if (!raw) return;
    let parsed = null;
    try {
      parsed = JSON.parse(raw);
    } catch {
      parsed = null;
    }
    let definitive = true;
    if (parsed && !structure?.customized && !structure?.migrated)
      try {
        adopt(await host.api.migrate({ layout: parsed }));
      } catch (error) {
        // Server refusals (invalid / already customized) are final; a
        // network failure keeps the layout for the next load.
        definitive = /^[a-z_]+$/.test(String(error?.message ?? ""));
      }
    if (definitive)
      try {
        globalThis.localStorage.removeItem(PROTOTYPE_LAYOUT_KEY);
      } catch {
        /* storage unavailable */
      }
  }
  async function refreshValues(force = false) {
    const now = Date.now();
    if (!force && now - lastValues < VALUES_MIN_GAP_MS) return;
    if (globalThis.document?.hidden) return;
    lastValues = now;
    try {
      values = await host.api.values();
    } catch (error) {
      if (error?.message !== "rate_limit")
        notice = "Could not read device values. Try again shortly.";
    }
    notify();
  }
  // Bounded refresh only while the strip or the house is showing.
  function syncValues() {
    const want = !!house || wantStrip;
    if (want && !valuesTimer) {
      void refreshValues();
      valuesTimer = setInterval(() => void refreshValues(), VALUES_EVERY_MS);
      valuesTimer?.unref?.();
    } else if (!want && valuesTimer) {
      clearInterval(valuesTimer);
      valuesTimer = 0;
    }
  }
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden && valuesTimer) void refreshValues();
  });
  const strip = createStrip(ctx);
  host.stripHost.append(strip.element);
  await load();
  return {
    update(next) {
      const wasBusy = think.busy;
      Object.assign(input, next);
      think = deriveThink(input.snapshot, input.kind);
      strip.element.hidden = input.kind !== "home";
      // Hearth may have changed something: read once when a run ends.
      if (wasBusy && !think.busy && (house || wantStrip))
        void refreshValues(true);
      notify();
    },
    openFull: (options) => ctx.openFull(options),
    closeFull: () => ctx.closeFull(),
    get fullOpen() {
      return !!house;
    },
  };
}
